function fieldValue(name){return $('#action-form')?.elements.namedItem(name)?.value||'';}
function eligible(o,f){const cmd=$('#action-select')?.value;
 if(['location','zone','calendar','service','resource'].includes(o.kind)&&o.status==='INACTIVE'&&!['master_update','fleet_update'].includes(cmd))return false;
 if(['order_create','import_preview','order_change'].includes(cmd)&&f.kind==='quote')return Number.isFinite(Date.parse(o.expiresAt))&&Date.parse(o.expiresAt)>Date.now();
 if(['order_create','import_preview','order_change'].includes(cmd)&&f.kind==='location'&&f.name.endsWith('locationId')){const q=get(fieldValue(f.name.startsWith('values.')?'values.quoteId':'quoteId'));return !q||o.postalCode===q.destinationCep;}
 if(cmd==='plan'&&f.name==='orderIds')return o.status==='RELEASED';
 if(cmd==='fleet_update'&&f.name==='id')return !state.objects.some(x=>(x.kind==='reservation'&&x.status==='ACTIVE'&&(x.resourceIds||[]).includes(o.id))||(x.kind==='maintenance'&&x.status==='SCHEDULED'&&x.resourceId===o.id));
 if(cmd==='invoice_create'&&f.name==='assignments')return o.carrierOrg===state.user.org&&get(o.shipmentId)?.status==='DELIVERED'&&!state.objects.some(i=>i.kind==='invoice'&&(i.assignmentIds||[]).includes(o.id));
 if(['settlement_request','reverse_request'].includes(cmd)&&f.name==='entryId'){if(o.side!=='AP'||o.type!=='POST'||get(o.invoiceId)?.status!=='POSTED_LOCAL')return false;const approvals=state.objects.filter(x=>x.kind==='approval'&&x.originalEntryId===o.id);const settled=state.objects.filter(x=>x.kind==='settlement'&&x.entryId===o.id).reduce((n,x)=>n+Math.round(Number(x.amount)*100),0);if(cmd==='reverse_request')return settled===0&&!approvals.some(a=>(a.type==='REVERSE'&&['PENDING','APPROVED'].includes(a.status))||(a.type==='SETTLEMENT'&&a.status==='PENDING'));const reserved=approvals.filter(a=>a.type==='SETTLEMENT'&&a.status==='PENDING').reduce((n,a)=>n+Math.round(Number(a.amount)*100),0);return get(o.invoiceId)?.status==='POSTED_LOCAL'&&settled+reserved<Math.round(Number(o.amount)*100)&&!approvals.some(a=>a.type==='REVERSE'&&a.status==='PENDING');}
 if(cmd==='invoice_audit'&&f.name==='id')return o.status==='RECEIVED';
 if(cmd==='approval_request'&&f.name==='invoiceId')return o.status==='AUDITED';
 if(cmd==='user_revoke'&&f.kind==='user')return o.id!==state.user.id&&o.active!==false&&o.active!==0;
 if(cmd==='user_roles'&&f.kind==='user')return o.id!==state.user.id;
 if(f.kind==='adapterConfig'){const expected=cmd==='label_request'?'CARRIER':cmd==='fiscal_evaluate'?'FISCAL':fieldValue('adapter');return !expected||o.adapter===expected;}
 if(f.kind==='shipment'){
  if(cmd==='label_request')return o.status==='ASSIGNED'&&o.labelStatus==='NONE';
  if(cmd==='stage')return ['ASSIGNED','IN_TRANSIT'].includes(o.status)&&o.stage!=='DELIVERY';
  if(['pod','upload_pod'].includes(cmd))return ['IN_TRANSIT','PARTIAL'].includes(o.status)&&o.stage==='DELIVERY';
  if(cmd==='tender')return ['PLANNED','OFFERED'].includes(o.status);
  if(cmd==='return_create')return (o.delivered||[]).length>0;
  if(cmd==='fiscal_evaluate')return o.status==='ASSIGNED'&&!['DEMO_AUTHORIZED','PENDING'].includes(o.fiscalStatus);
 }
 const states={approval_decide:['PENDING'],rate_publish:['DRAFT'],order_release:['VALIDATED'],plan_commit:['FEASIBLE'],claim_resolve:['OPEN'],expense_reconcile:['RECORDED'],expense_close:['OPEN_LOCAL'],maintenance_finish:['SCHEDULED'],outbox_process:['PENDING','RETRY'],outbox_query:['UNKNOWN'],outbox_requeue:['DLQ'],fiscal_cancel:['DEMO_AUTHORIZED']};
 if(states[cmd]&&f.name==='id')return states[cmd].includes(o.status);
 return true;
}
