async function renderMetrics(){
 const request=++metricsRequest;
 const b=$('#metrics');b.replaceChildren();
 try{
  const k=await api('/api/kpis');if(request!==metricsRequest)return;const s=k.shipments,p=k.packages,t=k.onTime,c=k.commercial;
  const cards=[metric('Viagens entregues',`${s.delivered} / ${s.total}`,'Entregas completas no conjunto visível'),metric('Volumes entregues',`${p.delivered} / ${p.total}`,'Inclui entregas parciais'),metric('No prazo',t.denominator?Math.round(t.numerator/t.denominator*100)+'%':'—',`${t.numerator} de ${t.denominator} avaliáveis · ${t.deliveredMissingPromiseOrActual} sem dados`),metric('Custo de transporte',money(c.cost),`${c.costCoverage} de ${c.orderDenominator} pedidos com custo`)];
  cards.forEach((card,i)=>{const btn=el('button','quiet','Ver composição');btn.onclick=()=>{
   if(i===2)drilldown('Pontualidade das entregas',[['No prazo',t.onTimeIds||[]],['Atrasadas',t.lateIds||[]],['Sem dados para avaliar',t.missingIds||[]]]);
   else if(i===3){drilldown('Composição comercial',[['Pedidos',state.objects.filter(o=>o.kind==='order'&&o.org===state.user.org&&o.status!=='CANCELLED').map(o=>o.id)]]);const box=$('#detail-body');box.append(el('p','',`Frete cobrado conhecido: ${money(c.charge)} · cobertura ${c.chargeCoverage}/${c.orderDenominator}`),el('p','',`Subsídio dos pares conhecidos: ${money(c.subsidyPaired)} · cobertura ${c.pairedCoverage}/${c.orderDenominator}`));}
   else drilldown(i===0?'Viagens do indicador':'Volumes por viagem',[['Viagens',s.ids||[]]]);
  };card.append(btn);});b.replaceChildren(...cards);
 }catch{
  if(request!==metricsRequest)return;b.replaceChildren();
  const ships=state.objects.filter(o=>o.kind==='shipment');b.append(metric('Viagens',String(ships.length),'Última consulta disponível'),metric('Pedidos',String(state.objects.filter(o=>o.kind==='order').length),'Histórico local'),metric('Entregues',String(ships.filter(o=>o.status==='DELIVERED').length),'Viagens concluídas'),metric('Envios pendentes',String(queue().length),'Neste dispositivo'));
 }
}
