function queueKey(){return 'rota-offline-'+(session?.user?.org||'')+'-'+(session?.user?.id||'');}function queue(){try{return JSON.parse(localStorage.getItem(queueKey())||'[]')}catch{return []}}function saveQueue(items){localStorage.setItem(queueKey(),JSON.stringify(items));updateQueue();}
function updateQueue(){const items=queue();$('#queue-count').textContent=items.length;$('#queue-panel').hidden=!items.length;$('#queue-list').replaceChildren();for(const item of items){const row=el('div','record');row.append(el('span','',`${definitions[item.command]?.[0]||'Registro'} · ${new Date(item.at).toLocaleString('pt-BR')}`));const del=el('button','quiet','Descartar');del.onclick=()=>{if(confirm('Descartar este registro ainda não sincronizado?'))saveQueue(queue().filter(x=>x.key!==item.key));};row.append(del);$('#queue-list').append(row);}if(!navigator.onLine){const cards=[...$('#metrics').querySelectorAll('.metric')];const pendingCard=cards.find(x=>x.textContent.includes('Envios pendentes'));if(pendingCard)pendingCard.querySelector('strong').textContent=items.length;}$('#connection').textContent=navigator.onLine?'Rede disponível':'Sem conexão';}
async function sync(){try{const current=await api('/api/session');if(current.user.id!==session.user.id||current.user.org!==session.user.org)throw new Error('Entre novamente com o usuário que registrou estas entregas.');session=current;for(const item of [...queue()]){if(!item.context)throw new Error(errors.OFFLINE_CONTEXT_REQUIRED);await api('/api/command',{method:'POST',body:{command:'offline_sync',payload:{command:item.command,payload:item.payload,context:item.context}},key:item.key});saveQueue(queue().filter(x=>x.key!==item.key));}await refresh();notify('Sincronização concluída.');}catch(e){notify('Sincronização interrompida: '+e.message,true);}}
